{"file_path":"_probe_select.gd","content":"extends Node

var _battle: Node = null
var _wait := 3.0
var _step := 0


func _ready() -> void:
	_battle = load("res://scenes/battle.tscn").instantiate()
	add_child(_battle)


func _process(delta: float) -> void:
	_wait -= delta
	if _wait > 0.0:
		return
	_wait = 1.0
	_step += 1
	if _step == 1:
		var ui: CanvasLayer = _battle.select_ui
		if ui == null:
			print("PROBE select_ui=null")
			get_tree().quit(1)
			return
		var root: Node = ui.get_node_or_null("SelectRoot")
		print("PROBE viewport=", get_viewport().get_visible_rect().size, " ui_scale=", UiKit.scale())
		var hc: Panel = root.find_child("HeroCard_亚瑟", true, false)
		var sc: Panel = root.find_child("SummCard_flash", true, false)
		print("PROBE cards hero=", hc != null, " summ=", sc != null)
		if hc:
			_battle._on_card_hover(hc, true, Color(0.85, 0.3, 0.2))
			_battle._on_card_hover(hc, false, Color(0.85, 0.3, 0.2))
			var ev := InputEventMouseButton.new()
			ev.button_index = MOUSE_BUTTON_LEFT
			ev.pressed = true
			ev.position = hc.get_global_rect().get_center()
			hc.gui_input.emit(ev)
		if sc:
			var ev2 := InputEventMouseButton.new()
			ev2.button_index = MOUSE_BUTTON_LEFT
			ev2.pressed = true
			ev2.position = sc.get_global_rect().get_center()
			sc.gui_input.emit(ev2)
		print("PROBE selected hero=", _battle.selected_hero_type, " summ=", _battle.selected_summoner)
	elif _step == 2:
		var ui: CanvasLayer = _battle.select_ui
		var root: Node = ui.get_node_or_null("SelectRoot")
		for nm in ["SelectRoot", "SelectMargin", "SelectMain", "SelectLeft", "SelectHeroScroll", "SelectMiddle", "SelectPreviewName", "SelectRight", "SelectBottom", "SelectLeave", "SelectConfirm"]:
			var n: Node = root.find_child(nm, true, false)
			if n == null:
				print("PROBE RECT ", nm, " MISSING")
			elif n is Control:
				var r: Rect2 = (n as Control).get_global_rect()
				print("PROBE RECT %s = (%.1f, %.1f, %.1f, %.1f)" % [nm, r.position.x, r.position.y, r.size.x, r.size.y])
		print("PROBE summary=", _battle.select_summary_label.text, " confirm_disabled=", _battle.select_confirm_btn.disabled)
		print("PROBE summ_detail=", _battle.select_summ_detail.text.replace("\n", " / "))
		await RenderingServer.frame_post_draw
		var img := get_viewport().get_texture().get_image()
		img.save_png("res://_probe_sel.png")
		print("PROBE shot=", img.get_size())
		get_tree().quit()
"}

