{"file_path":"scripts/core/BattleManager.gd","new_string":"# 立绘预览：切模型/职责色 + 左下角名称/标签/技能 chip（不改选人状态）
func _refresh_sel_preview(hero_name: String) -> void:
	if sel_prev_name == null: return
	var cfg: Dictionary = hero_configs.get(hero_name, {})
	if cfg.is_empty(): return
	var role: String = str(cfg.get("role", ""))
	var role_color: Color = ROLE_COLORS.get(role, UiKit.C_TEAM0)
	if sel_preview_3d:
		sel_preview_3d.set_hero(hero_name)
		sel_preview_3d.set_accent(role_color)
	sel_prev_name.text = hero_name
	sel_prev_name.add_theme_color_override("font_color", SEL_GOLD)
	if sel_prev_role_label:
		sel_prev_role_label.text = "定位 · " + role
		sel_prev_role_label.add_theme_color_override("font_color", role_color.lightened(0.35))
	if sel_prev_role_chip:
		sel_prev_role_chip.add_theme_stylebox_override("panel", UiKit.skin_chip(role_color, 0.95, 12))
	if sel_prev_info_label:
		sel_prev_info_label.text = "推荐召唤师 · " + _sel_summ_name(str(cfg.get("summoner", "flash")))
	if sel_prev_info_chip:
		sel_prev_info_chip.add_theme_stylebox_override("panel", UiKit.skin_chip(UiKit.C_GOLD, 0.9, 12))
	# 技能 1/2/3（+被动）横向 chip 行
	if sel_prev_skill_box:
		for c in sel_prev_skill_box.get_children():
			sel_prev_skill_box.remove_child(c)
			c.queue_free()
		var skills: Array = cfg.get("skills", [])
		for i in skills.size():
			var sk: Skill = SkillDatabase.get_skill(str(skills[i]))
			var chip := PanelContainer.new()
			chip.add_theme_stylebox_override("panel", UiKit.skin_chip(UiKit.C_TEAM0, 0.58, 12))
			var info := VBoxContainer.new()
			info.add_theme_constant_override("separation", 0)
			info.add_child(_sel_label("%d  %s" % [i + 1, str(sk.skill_name) if sk != null else str(skills[i])], _sel_fs(UiKit.FS_MD), SEL_TEXT, false))
			var meta := _sel_skill_type(int(sk.type) if sk != null else 0)
			if sk != null:
				meta += " · 冷却 %ds" % int(round(sk.cooldown))
				if sk.mana_cost > 0: meta += " · 法力 %d" % sk.mana_cost
			info.add_child(_sel_label(meta, _sel_fs(UiKit.FS_XS), SEL_DIM, false))
			chip.add_child(info)
			sel_prev_skill_box.add_child(chip)
","old_string":"# 中栏英雄预览：名称/职责标签/技能说明/基础属性（预览时调用，不改选人状态）
func _refresh_sel_preview(hero_name: String) -> void:
	if sel_prev_name == null: return
	var cfg: Dictionary = hero_configs.get(hero_name, {})
	if cfg.is_empty(): return
	var role: String = str(cfg.get("role", ""))
	var role_color: Color = ROLE_COLORS.get(role, UiKit.C_TEAM0)
	sel_prev_name.text = hero_name
	sel_prev_name.add_theme_color_override("font_color", Color.WHITE)
	if sel_prev_role_label:
		sel_prev_role_label.text = "定位 · " + role
		sel_prev_role_label.add_theme_color_override("font_color", role_color.lightened(0.35))
	if sel_prev_role_chip:
		sel_prev_role_chip.add_theme_stylebox_override("panel", UiKit.skin_chip(role_color, 0.95, 12))
	if sel_prev_info_label:
		sel_prev_info_label.text = "推荐召唤师 · " + _sel_summ_name(str(cfg.get("summoner", "flash")))
	if sel_prev_info_chip:
		sel_prev_info_chip.add_theme_stylebox_override("panel", UiKit.skin_chip(UiKit.C_GOLD, 0.9, 12))
	# 技能 1/2/3（+被动）
	if sel_prev_skill_box:
		for c in sel_prev_skill_box.get_children():
			sel_prev_skill_box.remove_child(c)
			c.queue_free()
		var skills: Array = cfg.get("skills", [])
		for i in skills.size():
			var sk: Skill = SkillDatabase.get_skill(str(skills[i]))
			var row := PanelContainer.new()
			row.custom_minimum_size = Vector2(0, 92)
			row.size_flags_vertical = Control.SIZE_EXPAND_FILL
			row.add_theme_stylebox_override("panel", UiKit.skin_chip(UiKit.C_TEAM0, 0.58, 12))
			var h := HBoxContainer.new()
			h.add_theme_constant_override("separation", 16)
			var key := _sel_label(str(i + 1), _sel_fs(UiKit.FS_XL), UiKit.C_GOLD)
			key.custom_minimum_size = Vector2(64, 0)
			key.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
			h.add_child(key)
			var info := VBoxContainer.new()
			info.size_flags_horizontal = Control.SIZE_EXPAND_FILL
			info.alignment = BoxContainer.ALIGNMENT_CENTER
			info.add_theme_constant_override("separation", 2)
			info.add_child(_sel_label(str(sk.skill_name) if sk != null else str(skills[i]), _sel_fs(UiKit.FS_MD), SEL_TEXT, false))
			var meta := "类型 " + _sel_skill_type(int(sk.type) if sk != null else 0)
			if sk != null:
				meta += "  ·  冷却 %ds" % int(round(sk.cooldown))
				if sk.mana_cost > 0:
					meta += "  ·  法力 %d" % sk.mana_cost
				if sk.damage > 0:
					meta += "  ·  伤害 %d" % int(round(sk.damage))
			var meta_label := _sel_label(meta, _sel_fs(UiKit.FS_SM), SEL_DIM, false)
			meta_label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
			info.add_child(meta_label)
			h.add_child(info)
			row.add_child(h)
			sel_prev_skill_box.add_child(row)
	# 基础属性两列
	if sel_prev_stats:
		for c in sel_prev_stats.get_children():
			sel_prev_stats.remove_child(c)
			c.queue_free()
		var stats := [
			["生命上限", int(cfg.get("max_health", 0))],
			["攻击力", int(cfg.get("attack", 0))],
			["攻击距离", int(cfg.get("attack_range", 0))],
			["移动速度", int(cfg.get("move_speed", 0))],
			["法力上限", int(cfg.get("max_mana", 0))],
			["生命回复/5s", int(cfg.get("hp_reg", 0))],
		]
		var cols: Array = [VBoxContainer.new(), VBoxContainer.new()]
		for col in cols:
			col.add_theme_constant_override("separation", 6)
			col.size_flags_horizontal = Control.SIZE_EXPAND_FILL
			sel_prev_stats.add_child(col)
		for i in stats.size():
			var st: Array = stats[i]
			var cell := HBoxContainer.new()
			cell.add_theme_constant_override("separation", 10)
			cell.size_flags_horizontal = Control.SIZE_EXPAND_FILL
			cell.add_child(_sel_label(str(st[0]), _sel_fs(UiKit.FS_SM), SEL_DIM, false))
			var val := _sel_label(str(st[1]), _sel_fs(UiKit.FS_MD), SEL_TEXT, false)
			val.size_flags_horizontal = Control.SIZE_EXPAND_FILL
			val.horizontal_alignment = HORIZONTAL_ALIGNMENT_RIGHT
			cell.add_child(val)
			cols[i % 2].add_child(cell)
"}

