Probe:

```gdscript
extends Node

var _battle: Node = null
var _wait := 3.0
var _step := 0


func _ready() -> void:
	_battle = load("res://scenes/battle.tscn").instantiate()
	add_child(_battle)


func _click_card(card: Control) -> void:
	var ev := InputEventMouseButton.new()
	ev.button_index = MOUSE_BUTTON_LEFT
	ev.pressed = true
	ev.position = card.get_global_rect().get_center()
	card.gui_input.emit(ev)


func _process(delta: float) -> void:
	_wait -= delta
	if _wait > 0.0:
		return
	_wait = 1.0
	_step += 1
	if _step == 1:
		var ui: CanvasLayer = _battle.select_ui
		if ui == null:
			print("PROBE select_ui=null")
			get_tree().quit(1)
			return
		var root: Node = ui.get_node_or_null("SelectRoot")
		print("PROBE viewport=", get_viewport().get_visible_rect().size, " ui_scale=", UiKit.scale(), " preview3d=", _battle.sel_preview_3d)
		var hc: Panel = root.find_child("HeroCard_亚瑟", true, false)
		var sc: Panel = root.find_child("SummCard_flash", true, false)
		print("PROBE cards hero=", hc != null, " summ=", sc != null)
		if hc: _click_card(hc)
		if sc: _click_card(sc)
		print("PROBE selected hero=", _battle.selected_hero_type, " summ=", _battle.selected_summoner)
	elif _step == 2:
		var ui: CanvasLayer = _battle.select_ui
		var root: Node = ui.get_node_or_null("SelectRoot")
		for nm in ["SelectRoot", "SelectMargin", "SelectTop", "SelectMiddle", "SelectOurSeats", "SelectStage", "SelectPreviewBox", "SelectHeroPreview", "SelectOverlay", "SelectPreviewName", "SelectFoeSeats", "SelectBottom", "SelectHeroStripScroll", "SelectRight", "SelectConfirm", "SelectLeave", "SelectHint", "SelectStageRing"]:
			var n: Node = null
			if nm == "SelectRoot":
				n = root
			else:
				n = root.find_child(nm, true, false)
			if n == null:
				print("PROBE RECT ", nm, " MISSING")
			elif n is Control:
				var r: Rect2 = (n as Control).get_global_rect()
				print("PROBE RECT %s = (%.1f, %.1f, %.1f, %.1f)" % [nm, r.position.x, r.position.y, r.size.x, r.size.y])
		print("PROBE preview model vp_children=", _battle.sel_preview_3d.get_child_count())
		var vp = _battle.sel_preview_3d.get_child(0)
		if vp:
			print("PROBE preview viewport size=", vp.size, " nodes=", vp.get_child_count())
			var model = vp.get_node_or_null("PreviewModel")
			print("PROBE preview model=", model, " model_children=", model.get_child_count() if model else -1)
		print("PROBE summary=", _battle.select_summary_label.text, " confirm_disabled=", _battle.select_confirm_btn.disabled)
		print("PROBE preview name=", _battle.sel_prev_name.text, " chips=", _battle.sel_prev_skill_box.get_child_count(), " seat_hero=", _battle.sel_seat_hero_label.text, " seat_summ=", _battle.sel_seat_summ_label.text, " mini=", _battle.sel_mini_hero_label.text)
		print("PROBE strip cards=", _battle.sel_hero_strip.get_child_count())
		var fcard: Panel = root.find_child("HeroCard_吕布", true, false)
		if fcard:
			var r3: Rect2 = fcard.get_global_rect()
			print("PROBE herocard ", r3)
		await RenderingServer.frame_post_draw
		var img := get_viewport().get_texture().get_image()
		img.save_png("res://_probe_sel.png")
		print("PROBE shot=", img.get_size())
	elif _step == 3:
		var ui: CanvasLayer = _battle.select_ui
		var root: Node = ui.get_node_or_null("SelectRoot")
		var tab: Button = root.find_child("SelectTab_法师", true, false)
		print("PROBE tab=", tab != null, " cards_before=", _battle.sel_hero_strip.get_child_count())
		if tab:
			tab.pressed.emit()
		print("PROBE cards_after_mage=", _battle.sel_hero_strip.get_child_count(), " active=", _battle.sel_active_role, " selected_card=", _battle.selected_hero_card)
		var tab2: Button = root.find_child("SelectTab_全部", true, false)
		if tab2:
			tab2.pressed.emit()
		print("PROBE cards_after_all=", _battle.sel_hero_strip.get_child_count())
		get_tree().quit()
```

Note type inference warnings: `var vp = ...` untyped fine in probe (probe is not project with warnings-as-errors? project settings may treat warnings as errors globally? Godot project settings has debug/gdscript/warnings ... The errors seen "Warning treated as error" are project setting. Probe script is also parsed with project settings → untyped `var vp = ...` produces Variant inference warning? That warning was about inference from Variant only for `:=`; plain `=` is untyped no warning. Use plain assignments. Also `var fcard: Panel = ...` typed fine. `var r3: Rect2` fine.

But probe `var model = vp.get_node_or_null(...)` plain fine.

`tab.pressed.emit()` — in GDScript, signal emit via `tab.pressed.emit()` valid.

Also `_battle.sel_preview_3d.get_child(0)` returns SubViewport (only child); HeroPreview adds viewport in _ready. Good.

Potential warnings: `if hc: _click_card(hc)` fine.

Probe scene as before.

Create files and run windowed.

