# AI 选人：优先补本队尚缺职责，同职责内随机
func _choose_ai_hero(team: int, seat: int) -> String:
	var team_picks: Array = sel_ally_picks if team == 0 else sel_enemy_picks
	var have_roles := {}
	for p in team_picks:
		var pname := str(p)
		if pname != "" and hero_configs.has(pname):
			have_roles[str(hero_configs[pname].get("role", ""))] = true
	var candidates: Array = []
	for r in ["刺客", "法师", "射手", "战士", "辅助"]:
		if have_roles.has(r): continue
		for hero_name in hero_configs:
			var hn := str(hero_name)
			if sel_taken.has(hn): continue
			if str(hero_configs[hero_name].get("role", "")) == r:
				candidates.append(hn)
		if not candidates.is_empty():
			return str(candidates[randi() % candidates.size()])
	# 缺职责无可用英雄：全体未选中随机
	return _random_untaken_hero()

func _ai_pick_current() -> void:
