		_lock_player_pick(selected_hero_type)
		return
	var pick := _choose_ai_hero(team, seat)
	if pick == "":
		_advance_draft()
		return
	if team == 0:
		sel_ally_picks[seat] = pick
	else:
		sel_enemy_picks[seat] = pick
