		dl.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
		dl.custom_minimum_size = Vector2(340, 0)
		v.add_child(dl)
	var tag := "已选" if sid == selected_summoner else ""
	if tag == "" and _hero_summ_id(selected_hero_type) == sid:
