{"content":"extends Node

var battle = null
var mode := "main"
var last_step := -1
var step_start := 0
var player_handled := false
var timeout_checked := false
var picks_snapshot := {}


func _ready() -> void:
	var args := OS.get_cmdline_user_args()
	if args.size() > 0:
		mode = str(args[0])
	battle = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().create_timer(2.5).timeout
	await _run()


func _click_card(card: Control) -> void:
	var ev := InputEventMouseButton.new()
	ev.button_index = MOUSE_BUTTON_LEFT
	ev.pressed = true
	ev.position = card.get_global_rect().get_center()
	card.gui_input.emit(ev)


func _find(nm: String) -> Node:
	if battle.select_ui == null:
		return null
	var root = battle.select_ui.get_node_or_null("SelectRoot")
	if root == null:
		return null
	return root.find_child(nm, true, false)


func _seat_desc(step: int) -> String:
	var order: Array = battle.SEL_DRAFT_ORDER
	var info: Array = order[clampi(step, 0, 9)]
	return "%s%d号位" % ["我方" if int(info[0]) == 0 else "敌方", int(info[1]) + 1]


func _step_pick(step: int) -> String:
	var order: Array = battle.SEL_DRAFT_ORDER
	var info: Array = order[clampi(step, 0, 9)]
	var arr: Array = battle.sel_ally_picks if int(info[0]) == 0 else battle.sel_enemy_picks
	var seat := int(info[1])
	if seat < arr.size():
		return str(arr[seat])
	return ""


func _run() -> void:
	var b = battle
	print("PROBE mode=", mode)
	print("PROBE seat=", b.sel_player_seat, " draft=", b.sel_draft_active, " step=", b.sel_draft_step, " time=", snappedf(b.sel_draft_time, 0.01))
	print("PROBE stage='", b.sel_stage_sub_label.text, "' ring=", b.sel_stage_ring_label.text, " confirm='", b.select_confirm_btn.text, "' disabled=", b.select_confirm_btn.disabled)
	for i in 5:
		var kind := "玩家" if i == b.sel_player_seat else "AI"
		print("PROBE seat%d kind=%s hero='%s' summ='%s'" % [i + 1, kind, b.sel_ally_hero_labels[i].text, b.sel_ally_summ_labels[i].text])
	# 悬停浮层
	var scard: Panel = _find("SummCard_flash")
	if scard:
		scard.mouse_entered.emit()
		await get_tree().process_frame
		var hp = b.sel_hover_panel
		print("PROBE hover visible=", hp != null and hp.visible, " w=", hp.custom_minimum_size.x if hp != null else 0, " rect=", (hp.get_global_rect() if hp != null else Rect2()))
		scard.mouse_exited.emit()
		await get_tree().process_frame
		print("PROBE hover hidden=", b.sel_hover_panel == null)
	# 出装 tab
	var bt: Button = _find("SelectBuildTab")
	if bt:
		bt.pressed.emit()
		await get_tree().process_frame
		print("PROBE buildtab visible=", b.sel_build_panel.visible, " summ_visible=", b.sel_summ_panel.visible, " ids=", b.sel_build_ids)
		var up: Button = _find("BuildUp_2")
		if up:
			up.pressed.emit()
			await get_tree().process_frame
			print("PROBE build after up ids=", b.sel_build_ids, " override=", ItemDatabase.get_recommended_override(b.sel_build_hero))
		var restore: Button = _find("SelectBuildRestore")
		if restore:
			restore.pressed.emit()
			await get_tree().process_frame
			print("PROBE build restored ids=", b.sel_build_ids, " override=", ItemDatabase.get_recommended_override(b.sel_build_hero))
		var st: Button = _find("SelectSummTab")
		if st:
			st.pressed.emit()
	# 10 步流程
	step_start = Time.get_ticks_msec()
	var t0 := Time.get_ticks_msec()
	while true:
		if b.select_ui == null:
			break
		if b.sel_draft_done:
			picks_snapshot = {"ally": b.sel_ally_picks.duplicate(), "enemy": b.sel_enemy_picks.duplicate()}
			print("PROBE draft_done picks ally=", picks_snapshot["ally"], " enemy=", picks_snapshot["enemy"])
			break
		if not b.sel_draft_active:
			break
		if b.sel_draft_step != last_step:
			if last_step >= 0:
				print("PROBE step%d %s -> %s (%.2fs)" % [last_step + 1, _seat_desc(last_step), _step_pick(last_step), (Time.get_ticks_msec() - step_start) / 1000.0])
			last_step = b.sel_draft_step
			step_start = Time.get_ticks_msec()
			print("PROBE step%d begin %s player_turn=%s time_limit=%.1f" % [b.sel_draft_step + 1, _seat_desc(b.sel_draft_step), b._is_player_turn(), b.SEL_DRAFT_TURN_TIME])
		if b._is_player_turn() and not player_handled:
			player_handled = true
			await RenderingServer.frame_post_draw
			var img := get_viewport().get_texture().get_image()
			img.save_png("res://screenshots/select_draft.png")
			print("PROBE shot=", img.get_size())
			var pick_name := ""
			for hn in b.hero_configs:
				if not b.sel_taken.has(str(hn)):
					pick_name = str(hn)
					break
			var hc: Panel = _find("HeroCard_" + pick_name)
			if hc:
				_click_card(hc)
				await get_tree().process_frame
			print("PROBE player preview='", b.selected_hero_type, "' clicked='", pick_name, "'")
			var sc: Panel = _find("SummCard_sprint")
			if sc:
				_click_card(sc)
				await get_tree().process_frame
			print("PROBE manual summ='", b.selected_summoner, "' manual=", b.sel_summ_manual)
			if mode == "timeout":
				b.sel_draft_time = 0.05
				print("PROBE set_time=0.05 expect auto lock preview")
			else:
				b.select_confirm_btn.pressed.emit()
				await get_tree().process_frame
				print("PROBE after_confirm picked=", b.sel_player_picked, " pick='", b.sel_ally_picks[b.sel_player_seat], "' step=", b.sel_draft_step + 1, " btn='", b.select_confirm_btn.text, "' disabled=", b.select_confirm_btn.disabled)
		if mode == "timeout" and player_handled and b.sel_player_picked and not timeout_checked:
			timeout_checked = true
			print("PROBE timeout_locked pick='", b.sel_ally_picks[b.sel_player_seat], "' preview='", b.selected_hero_type, "' step=", b.sel_draft_step + 1)
		await get_tree().process_frame
		if Time.get_ticks_msec() - t0 > 90000:
			print("PROBE TIMEOUT waiting draft")
			break
	await get_tree().create_timer(1.5).timeout
	if b.hero != null:
		print("PROBE game player='", b.hero.display_name, "' team=", b.hero.team)
		var heroes := get_tree().get_nodes_in_group("heroes")
		var lines := []
		for h in heroes:
			lines.append("%s(team%d,ai=%s)" % [h.display_name, h.team, str(h.is_ai)])
		lines.sort()
		print("PROBE game heroes=", lines, " count=", heroes.size())
		print("PROBE heroes_match=", _check_heroes(picks_snapshot), " snapshot=", picks_snapshot)
	else:
		print("PROBE game NOT started, select_ui=", b.select_ui)
	get_tree().quit()


func _check_heroes(snap: Dictionary) -> bool:
	var ally_picks: Array = snap.get("ally", [])
	var enemy_picks: Array = snap.get("enemy", [])
	var heroes := get_tree().get_nodes_in_group("heroes")
	if heroes.size() != 10:
		return false
	var ally_names := []
	var enemy_names := []
	for h in heroes:
		if h.team == 0:
			ally_names.append(str(h.display_name))
		else:
			enemy_names.append(str(h.display_name))
	if not ally_names.has(str(battle.selected_hero_type)):
		return false
	for p in ally_picks:
		var pn := str(p)
		if pn != "" and pn != str(battle.selected_hero_type) and not ally_names.has(pn):
			return false
	for p in enemy_picks:
		var pn := str(p)
		if pn != "" and not enemy_names.has(pn):
			return false
	return true
","file_path":"_probe_draft.gd"}

