{"content":"extends Node

var battle = null
var picks_snapshot := {}
var loading_shot := false
var scheme_tested := false


func _ready() -> void:
	battle = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().create_timer(2.5).timeout
	await _run()


func _find(nm: String) -> Node:
	if battle.select_ui == null:
		return null
	var root = battle.select_ui.get_node_or_null("SelectRoot")
	if root == null:
		return null
	return root.find_child(nm, true, false)


func _click_card(card: Control) -> void:
	if card == null:
		return
	var ev := InputEventMouseButton.new()
	ev.button_index = MOUSE_BUTTON_LEFT
	ev.pressed = true
	ev.position = card.get_global_rect().get_center()
	card.gui_input.emit(ev)


func _scheme_names() -> Array:
	var out := []
	var row := _find("SelectBuildSchemeRow")
	if row != null:
		for c in row.get_children():
			out.append(str(c.name))
	return out


func _run() -> void:
	var b = battle
	var had_save := FileAccess.file_exists(HeroBuildStore.SAVE_PATH)
	var ids := ["battle_axe", "resist_boots", "ice_fist", "sage_power", "fierce_armor", "omen"]
	var err := HeroBuildStore.save_build("亚瑟", "测试流", ids)
	print("PROBE save_build err='", err, "' builds=", HeroBuildStore.get_builds("亚瑟").size(), " had_save=", had_save)
	# 切到亚瑟（未选，可预览）→ 出装 tab
	_click_card(_find("HeroCard_亚瑟"))
	await get_tree().process_frame
	print("PROBE hero='", b.selected_hero_type, "' schemes=", _scheme_names())
	var bt: Button = _find("SelectBuildTab")
	if bt:
		bt.pressed.emit()
		await get_tree().process_frame
	print("PROBE buildtab visible=", b.sel_build_panel.visible, " schemes=", _scheme_names(), " ids=", b.sel_build_ids)
	var sb: Button = _find("BuildScheme_0")
	if sb:
		sb.pressed.emit()
		await get_tree().process_frame
	print("PROBE scheme0 text='", (sb.text if sb != null else ""), "' ids=", b.sel_build_ids, " override=", ItemDatabase.get_recommended_override("亚瑟"))
	var db: Button = _find("BuildScheme_default")
	if db:
		db.pressed.emit()
		await get_tree().process_frame
	var role_default: Array = ItemDatabase.get_recommended_items("战士")
	print("PROBE default ids=", b.sel_build_ids, " role_default=", role_default, " override=", ItemDatabase.get_recommended_override("亚瑟"), " eq=", b.sel_build_ids == role_default)
	# 切英雄验证方案行重建
	_click_card(_find("HeroCard_李白"))
	await get_tree().process_frame
	print("PROBE switch 李白 schemes=", _scheme_names())
	scheme_tested = true
	# 清理测试存档
	HeroBuildStore.delete_build("亚瑟", "测试流")
	if not had_save:
		var path := ProjectSettings.globalize_path(HeroBuildStore.SAVE_PATH)
		if FileAccess.file_exists(path):
			DirAccess.remove_absolute(path)
	var fb := ProjectSettings.globalize_path(HeroBuildStore.FALLBACK_PATH)
	if FileAccess.file_exists(fb) and (FileAccess.get_file_as_string(fb).strip_edges() == "{}" or FileAccess.get_file_as_string(fb).strip_edges() == ""):
		DirAccess.remove_absolute(fb)
	print("PROBE save cleaned builds=", HeroBuildStore.get_builds("亚瑟").size())
	# 加速跑完 BP → 等 loading
	var t0 := Time.get_ticks_msec()
	while b.select_ui != null:
		if b.loading_screen != null:
			if picks_snapshot.is_empty():
				picks_snapshot = {"ally": b.sel_ally_picks.duplicate(), "enemy": b.sel_enemy_picks.duplicate()}
				print("PROBE loading shown heroes=", b.loading_screen._heroes.size(), " data=", b.loading_screen._heroes)
				await get_tree().create_timer(0.8).timeout
				await RenderingServer.frame_post_draw
				var img := get_viewport().get_texture().get_image()
				img.save_png("res://screenshots/loading_bp.png")
				print("PROBE loading shot=", img.get_size(), " loading_visible=", b.loading_screen != null and b.loading_screen.visible)
				loading_shot = true
			await get_tree().process_frame
			if Time.get_ticks_msec() - t0 > 30000:
				print("PROBE TIMEOUT waiting body")
				break
			continue
		if not b.sel_draft_active and not b.sel_draft_done:
			break
		if b.sel_draft_active:
			b.sel_draft_time = 0.05
		await get_tree().process_frame
		if Time.get_ticks_msec() - t0 > 30000:
			print("PROBE TIMEOUT waiting draft")
			break
	var t1 := Time.get_ticks_msec()
	while b.hero == null and Time.get_ticks_msec() - t1 < 30000:
		await get_tree().process_frame
	print("PROBE body started bm.hero=", (b.hero != null), " hero='", (b.hero.display_name if b.hero != null else ""), "'")
	await get_tree().create_timer(0.6).timeout
	if b.hero != null:
		var heroes := get_tree().get_nodes_in_group("heroes")
		var lines := []
		for h in heroes:
			lines.append("%s(team%d,ai=%s)" % [h.display_name, h.team, str(h.is_ai)])
		lines.sort()
		print("PROBE game heroes=", lines, " count=", heroes.size())
		print("PROBE picks snapshot=", picks_snapshot)
		print("PROBE heroes_match=", _check_heroes(picks_snapshot))
	print("PROBE loading_shot=", loading_shot, " scheme_tested=", scheme_tested)
	get_tree().quit()


func _check_heroes(snap: Dictionary) -> bool:
	var ally_picks: Array = snap.get("ally", [])
	var enemy_picks: Array = snap.get("enemy", [])
	var heroes := get_tree().get_nodes_in_group("heroes")
	if heroes.size() != 10:
		return false
	var ally_names := []
	var enemy_names := []
	for h in heroes:
		if h.team == 0:
			ally_names.append(str(h.display_name))
		else:
			enemy_names.append(str(h.display_name))
	if not ally_names.has(str(battle.selected_hero_type)):
		return false
	for p in ally_picks:
		var pn := str(p)
		if pn != "" and pn != str(battle.selected_hero_type) and not ally_names.has(pn):
			return false
	for p in enemy_picks:
		var pn := str(p)
		if pn != "" and not enemy_names.has(pn):
			return false
	return true
