{"content":"extends Node

var battle = null


func _ready() -> void:
	battle = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().create_timer(2.5).timeout
	await _run()


func _find(nm: String) -> Node:
	if battle.select_ui == null:
		return null
	var root = battle.select_ui.get_node_or_null("SelectRoot")
	if root == null:
		return null
	return root.find_child(nm, true, false)


func _click(card: Control) -> void:
	if card == null:
		return
	var ev := InputEventMouseButton.new()
	ev.button_index = MOUSE_BUTTON_LEFT
	ev.pressed = true
	ev.position = card.get_global_rect().get_center()
	card.gui_input.emit(ev)


func _roles_of(names: Array) -> Array:
	var roles: Array = []
	for n in names:
		var r: String = battle._hero_role(str(n))
		if r != "" and not roles.has(r):
			roles.append(r)
	return roles


func _run() -> void:
	var b = battle
	var all_roles := ["战士", "法师", "刺客", "射手", "辅助"]
	# ---- 构造冲突：队友（非玩家席位）已选射手 ----
	var seat: int = (b.sel_player_seat + 1) % 5
	var before := str(b.selected_hero_type)
	b.sel_ally_picks[seat] = "孙尚香"
	b._refresh_pick_display()
	b._rebuild_hero_strip()
	b._update_confirm_button_style()
	await get_tree().process_frame
	print("PROBE fake_seat=", seat, " player_seat=", b.sel_player_seat, " team_roles=", b._team_roles_taken(0))
	print("PROBE can_pick_孙尚香=", b._can_pick_hero("孙尚香", 0), " can_pick_亚瑟=", b._can_pick_hero("亚瑟", 0), " selected_before=", before)
	_click(_find("HeroCard_孙尚香"))
	await get_tree().process_frame
	print("PROBE click_lock selected_after=", b.selected_hero_type, " unchanged=", str(b.selected_hero_type) == before, " tip='", (b.sel_tip_label.text if b.sel_tip_label != null else ""), "' tip_visible=", (b.sel_tip_label.visible if b.sel_tip_label != null else false))
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://screenshots/select_role_lock.png")
	print("PROBE shot=", img.get_size())
	# 还原假席位
	b.sel_ally_picks[seat] = ""
	b._refresh_pick_display()
	b._rebuild_hero_strip()
	# ---- 加速跑完 BP，检查双方 5 职责唯一 ----
	var picks_snapshot := {}
	var t0 := Time.get_ticks_msec()
	while b.hero == null and Time.get_ticks_msec() - t0 < 40000:
		if b.loading_screen != null:
			if picks_snapshot.is_empty():
				picks_snapshot = {"ally": b.sel_ally_picks.duplicate(), "enemy": b.sel_enemy_picks.duplicate()}
				var ar := _roles_of(picks_snapshot["ally"])
				var er := _roles_of(picks_snapshot["enemy"])
				print("PROBE final_ally=", picks_snapshot["ally"], " roles=", ar, " n=", ar.size())
				print("PROBE final_enemy=", picks_snapshot["enemy"], " roles=", er, " n=", er.size())
				print("PROBE roles_ok=", ar.size() == 5 and er.size() == 5 and ar.size() == all_roles.size() and er.size() == all_roles.size())
			await get_tree().process_frame
			continue
		if b.sel_draft_active:
			b.sel_draft_time = 0.05
		await get_tree().process_frame
	print("PROBE body_started=", b.hero != null)
	await get_tree().create_timer(0.6).timeout
	var heroes := get_tree().get_nodes_in_group("heroes")
	var ally_names := []
	var enemy_names := []
	for h in heroes:
		if h.team == 0: ally_names.append(str(h.display_name))
		else: enemy_names.append(str(h.display_name))
	print("PROBE game_heroes=", heroes.size(), " ally_roles=", _roles_of(ally_names), " enemy_roles=", _roles_of(enemy_names))
	print("PROBE game_roles_ok=", _roles_of(ally_names).size() == 5 and _roles_of(enemy_names).size() == 5)
	get_tree().quit()
","file_path":"_probe_t20.gd"}

