	var pool: Array = []
	for hero_name in hero_configs:
		var hn := str(hero_name)
		if sel_taken.has(hn) or not _is_player_role(hn): continue
		pool.append(hn)
	if pool.is_empty(): return ""
	return str(pool[randi() % pool.size()])

