{"content":"extends Node

var battle = null
var lane := "发育路"


func _ready() -> void:
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--lane="):
			lane = a.substr(7)
	PlayerPrefs.set_lane(lane)
	battle = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	# 等选人页出现（此时 BP 刚开始，尚未有 AI 落子）
	var t0 := Time.get_ticks_msec()
	while battle.select_ui == null and Time.get_ticks_msec() - t0 < 15000:
		await get_tree().process_frame
	await get_tree().process_frame
	# 冻结 BP 做静态检查/截图，避免 AI 抢先落子影响断言
	battle.sel_draft_active = false
	await _run()


func _find(nm: String) -> Node:
	if battle.select_ui == null:
		return null
	var root = battle.select_ui.get_node_or_null("SelectRoot")
	if root == null:
		return null
	return root.find_child(nm, true, false)


func _click(card: Control) -> void:
	if card == null:
		return
	var ev := InputEventMouseButton.new()
	ev.button_index = MOUSE_BUTTON_LEFT
	ev.pressed = true
	ev.position = card.get_global_rect().get_center()
	card.gui_input.emit(ev)


func _labels_of(node: Node, out: Array) -> void:
	if node == null:
		return
	if node is Label:
		out.append(str((node as Label).text))
	for c in node.get_children():
		_labels_of(c, out)


func _roles_of(names: Array) -> Array:
	var roles: Array = []
	for n in names:
		var r: String = battle._hero_role(str(n))
		if r != "" and not roles.has(r):
			roles.append(r)
	return roles


func _run() -> void:
	var b = battle
	var all_roles := ["战士", "法师", "刺客", "射手", "辅助"]
	print("PROBE lane=", b.sel_lane_name, " lane_role=", b.sel_lane_role, " player_seat=", b.sel_player_seat, " draft_active_frozen=", b.sel_draft_active)
	print("PROBE initial_hero=", b.selected_hero_type, " role=", b._hero_role(b.selected_hero_type), " first_lane=", b._first_lane_hero(), " build_hero=", b.sel_build_hero)
	print("PROBE can 孙尚香=", b._can_player_pick("孙尚香"), " 妲己=", b._can_player_pick("妲己"), " random_lane=", b._random_lane_hero())
	var hint: Label = _find("SelectHint")
	print("PROBE hint='", (hint.text if hint != null else ""), "'")
	var seat_texts: Array = []
	_labels_of(_find("SeatOur_%d" % (b.sel_player_seat + 1)), seat_texts)
	print("PROBE seat_texts=", seat_texts)
	var mini_texts: Array = []
	_labels_of(_find("MiniOur_%d" % (b.sel_player_seat + 1)), mini_texts)
	print("PROBE mini_texts=", mini_texts)
	# 分路不符点击：点法师，选择不应改变
	var before := str(b.selected_hero_type)
	_click(_find("HeroCard_妲己"))
	await get_tree().process_frame
	print("PROBE click offlane selected_after=", b.selected_hero_type, " unchanged=", str(b.selected_hero_type) == before, " tip='", (b.sel_tip_label.text if b.sel_tip_label != null else ""), "' tip_visible=", (b.sel_tip_label.visible if b.sel_tip_label != null else false))
	if lane == "发育路":
		await RenderingServer.frame_post_draw
		var img := get_viewport().get_texture().get_image()
		img.save_png("res://screenshots/select_lane.png")
		print("PROBE shot=", img.get_size())
	# 解冻并压小回合时间快进完整 BP
	b.sel_draft_active = true
	var snap := {}
	var t1 := Time.get_ticks_msec()
	while b.hero == null and Time.get_ticks_msec() - t1 < 40000:
		if b.loading_screen != null:
			if snap.is_empty():
				snap = {"ally": b.sel_ally_picks.duplicate(), "enemy": b.sel_enemy_picks.duplicate()}
				var ally: Array = snap["ally"]
				var enemy: Array = snap["enemy"]
				var player_pick := str(ally[b.sel_player_seat])
				var others: Array = []
				for i in 5:
					if i != b.sel_player_seat and str(ally[i]) != "":
						others.append(str(ally[i]))
				var ally_roles := _roles_of(ally)
				var enemy_roles := _roles_of(enemy)
				var other_roles := _roles_of(others)
				print("PROBE final_ally=", ally, " player_pick=", player_pick, " player_role=", b._hero_role(player_pick))
				print("PROBE final_enemy=", enemy)
				print("PROBE ally_roles=", ally_roles, " enemy_roles=", enemy_roles)
				print("PROBE player_role_ok=", b._hero_role(player_pick) == b.sel_lane_role, " teammate_no_lane=", not other_roles.has(b.sel_lane_role), " roles_ok=", ally_roles.size() == 5 and enemy_roles.size() == 5)
			await get_tree().process_frame
			continue
		if b.sel_draft_active:
			b.sel_draft_time = 0.0
		await get_tree().process_frame
	print("PROBE body_started=", b.hero != null)
	await get_tree().create_timer(0.6).timeout
	var heroes := get_tree().get_nodes_in_group("heroes")
	var ally_names := []
	var enemy_names := []
	var player_name := ""
	for h in heroes:
		if h.team == 0:
			ally_names.append(str(h.display_name))
			if not h.is_ai:
				player_name = str(h.display_name)
		else:
			enemy_names.append(str(h.display_name))
	print("PROBE game_heroes=", heroes.size(), " player_hero=", player_name, " player_role=", b._hero_role(player_name), " ally_roles=", _roles_of(ally_names), " enemy_roles=", _roles_of(enemy_names))
	print("PROBE game_roles_ok=", _roles_of(ally_names).size() == 5 and _roles_of(enemy_names).size() == 5)
	PlayerPrefs.set_lane("对抗路")
	for p in [PlayerPrefs.SAVE_PATH, PlayerPrefs.FALLBACK_PATH]:
		var abs := ProjectSettings.globalize_path(p)
		if FileAccess.file_exists(abs):
			DirAccess.remove_absolute(abs)
	var saves_dir := ProjectSettings.globalize_path("res://saves")
	if DirAccess.dir_exists_absolute(saves_dir) and DirAccess.get_files_at(saves_dir).is_empty() and DirAccess.get_directories_at(saves_dir).is_empty():
		DirAccess.remove_absolute(saves_dir)
	print("PROBE cleaned lane_now=", PlayerPrefs.get_lane())
	get_tree().quit()
","file_path":"_probe_t21.gd"}

